package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.*;
/** Native order draft for the three new Home styles. Uses the existing guarded layout store. */
final class FavoriteOrderEditor {
    static void show(Activity a){
        if(!LauncherLock.require(a,()->show(a)))return;
        try{
            Config config=Config.load(a);String profile=ProfileStore.id(),stamp=DesktopLayout.orderStamp(a);Map<String,?> before=ProfileStore.preferences(a).getAll();JSONObject saved=new JSONObject(DesktopLayout.capture(a,config));List<String> original=new ArrayList<>(DesktopLayout.draftFromSaved(saved.toString()).favorites);List<List<String>> draft=new ArrayList<>();draft.add(new ArrayList<>(original));
            Map<String,String> names=new HashMap<>();for(String pkg:original){String label=config.appLabels.get(pkg);if(label==null)try{label=a.getPackageManager().getApplicationLabel(a.getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception missing){label=pkg;}names.put(pkg,ProductFeatures.label(a,pkg,label));}
            ScrollView scroll=new ScrollView(a);LinearLayout rows=new LinearLayout(a);rows.setOrientation(LinearLayout.VERTICAL);int pad=dp(a,16);rows.setPadding(pad,dp(a,8),pad,dp(a,8));scroll.addView(rows);FrameLayout viewport=new FrameLayout(a);int height=Math.max(dp(a,96),Math.min(dp(a,252),a.getResources().getDisplayMetrics().heightPixels-dp(a,264)));viewport.addView(scroll,new FrameLayout.LayoutParams(-1,height));String[] focus={original.get(0)};int[] direction={1};View[] preferredFocus={null};Runnable[] render={null};
            render[0]=()->{rows.removeAllViews();View[] target={null},fallback={null};for(int i=0;i<draft.get(0).size();i++){final int index=i;String pkg=draft.get(0).get(i);LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);TextView name=new TextView(a);name.setText((i+1)+". "+names.get(pkg));name.setTextSize(17);name.setTextColor(-1);name.setTypeface(SettingsTypography.regular(a));name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));for(int delta:new int[]{-1,1}){TextView move=new TextView(a);move.setText(delta<0?"Move up":"Move down");move.setTextSize(15);move.setTypeface(SettingsTypography.medium(a));move.setTextColor(-1);move.setGravity(Gravity.CENTER);move.setFocusable(true);move.setClickable(true);move.setBackgroundResource(R.drawable.freedom_settings_chip);move.setEnabled(delta<0?i>0:i<draft.get(0).size()-1);move.setAlpha(move.isEnabled()?1:.35f);move.setContentDescription(names.get(pkg)+", "+(delta<0?"move up":"move down"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(a,92),dp(a,48));p.setMarginStart(dp(a,8));row.addView(move,p);if(pkg.equals(focus[0])&&move.isEnabled()){if(delta==direction[0])target[0]=move;if(fallback[0]==null)fallback[0]=move;}move.setOnClickListener(v->{draft.set(0,FavoriteOrderPolicy.move(draft.get(0),index,delta));focus[0]=pkg;direction[0]=delta;render[0].run();});}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(a,8);rows.addView(row,p);}View desired=target[0]!=null?target[0]:fallback[0];preferredFocus[0]=desired;if(desired!=null)desired.post(()->{if(desired.isShown())desired.requestFocusFromTouch();});};
            AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Arrange apps").setMessage("Move favourites up or down. Apply saves their order in this profile; Cancel keeps the current order.").setView(viewport).setNegativeButton(android.R.string.cancel,null).setPositiveButton("Apply",(d,w)->{
                try{Config.load(a);SharedPreferences p=ProfileStore.preferences(a);if(!LauncherLock.open(a)||!profile.equals(ProfileStore.id())||!before.equals(p.getAll())||!stamp.equals(DesktopLayout.orderStamp(a)))throw new IllegalStateException("Home changed. Open Arrange apps again.");if(original.equals(draft.get(0)))return;saved.getJSONObject("layout").put("favorites",new JSONArray(draft.get(0)));saved.put("dock",new JSONArray(draft.get(0)));DesktopLayout.draftFromSaved(saved.toString());Map<String,Object> values=new HashMap<>();values.put(DesktopLayout.STATE,saved.toString());values.put(DesktopLayout.UNDO,null);values.put(DesktopLayout.GUARD,null);values.put(DesktopLayout.UNDO_POSITION,null);values.put(Config.SETTINGS_REVISION_KEY,p.getLong(Config.SETTINGS_REVISION_KEY,0)+1);ProductFeatures.beforeChange(a,"Arrange favorite apps");if(!SetupValues.commit(p,values))throw new IllegalStateException("Could not save app order");a.getContentResolver().notifyChange(DesktopLayout.uri(a),null);a.setResult(Activity.RESULT_OK);a.finish();}catch(Exception failed){Toast.makeText(a,failed.getMessage(),Toast.LENGTH_LONG).show();}
            }).create();dialog.setOnShowListener(d->{render[0].run();dialog.getWindow().getDecorView().getViewTreeObserver().addOnWindowFocusChangeListener(has->{if(has&&dialog.getCurrentFocus()==null&&preferredFocus[0]!=null)preferredFocus[0].requestFocusFromTouch();});});dialog.show();
        }catch(Exception failed){Toast.makeText(a,failed.getMessage(),Toast.LENGTH_LONG).show();}
    }
    private static int dp(Activity a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
    private FavoriteOrderEditor(){}
}
